from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); comp=[[-1]*w for _ in range(h)]; seeds={}; cid=0
    for r in range(h):
      for c in range(w):
        if grid[r][c] and comp[r][c]<0:
          q=[(r,c)]; comp[r][c]=cid; color=None
          for y,x in q:
            v=grid[y][x]
            if v not in (0,1): color=v
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              ny,nx=y+dy,x+dx
              if 0<=ny<h and 0<=nx<w and grid[ny][nx] and comp[ny][nx]<0:
                comp[ny][nx]=cid; q.append((ny,nx))
          seeds[cid]=color; cid+=1
    out=[row[:] for row in grid]
    for r in range(1,h-1):
      for c in range(1,w-1):
        co=comp[r][c]
        if grid[r][c] and seeds.get(co) is not None and all(comp[y][x]==co for y in range(r-1,r+2) for x in range(c-1,c+2)):
          out[r][c]=seeds[co]
    return out
